// CP143: signature line + full name + "Generated By" on the remaining four PDFs (Reports, Audit Log, Maintenance History, My Reports).
// HTML-STRING tests only (mocked: no PDF rendering, no browser). Real rendering: tools/browser-tests/group3/t36_cp143_remaining_pdf_signatures.js.
const test = require('node:test'), assert = require('node:assert'), fs = require('node:fs'), path = require('node:path'), { pathToFileURL } = require('node:url')
const UT = path.join(__dirname, '../../client/src/utils'), U = f => import(pathToFileURL(path.join(UT, f)).href)
const me = { full_name: 'Juan P. Dela Cruz', surname: 'Dela Cruz', first_name: 'Juan', middle_initial: 'P', role: 'MIS' }
async function pdfs(empty = false) {
  global.localStorage = { getItem: () => JSON.stringify(me) }
  const [R, A, H, M] = await Promise.all(['reportsPdf.js', 'auditLogPdf.js', 'maintenanceHistoryPdf.js', 'myReportsPdf.js'].map(U))
  return {
    Reports: R.buildReportsPdfHtml('Reservation Reports', ['reserved_by', 'status'], empty ? [] : [{ reserved_by: 'Ana', status: 'APPROVED' }], { search: 'ana' }),
    'Audit Log': A.buildAuditLogPdfHtml(empty ? [] : [{ action: 'LOGIN', description: 'x', created_at: '2026-01-01T00:00:00Z', full_name: 'A B', username: '1', role: 'MIS' }], { roleLabel: () => 'Super Admin' }),
    'Maintenance History': H.buildMaintenanceHistoryPdfHtml(empty ? [] : [{ id: 1, status: 'PENDING', issue_description: 'x', reported_by_name: 'A B' }], { getAsset: () => ({ tag: 'T1', type: 'Computer', name: '' }) }),
    'My Reports': M.buildMyReportsPdfHtml(empty ? [] : [{ id: 1, status: 'PENDING', issue_description: 'x', computer_name: 'PC-1' }]),
  }
}
test('all four show "Generated By" with the user name and no "Printed by"', async () => {
  for (const [n, h] of Object.entries(await pdfs())) { assert.match(h, /<p class="clms-pdf-printed-by">Generated By: Dela Cruz, Juan, P\.<\/p>/, n); assert.doesNotMatch(h, /Printed by/i, n) }
})
test('exactly one signature line with the full name below it, as the last table row (so final page only)', async () => {
  for (const empty of [false, true]) for (const [n, h] of Object.entries(await pdfs(empty))) {
    assert.equal((h.match(/class="clms-pdf-signature__line"/g) || []).length, 1, n)
    assert.match(h, /clms-pdf-signature__line"><\/div><p class="clms-pdf-signature__name">Juan P\. Dela Cruz<\/p>/, n)
    assert.match(h, /<tr class="clms-pdf-signature-row"><td colspan="\d+">[\s\S]*?<\/td><\/tr><\/tbody><\/table>/, n)
    const cols = ((h.match(/<thead>[\s\S]*?<\/thead>/) || [''])[0].match(/<th[\s>]/g) || []).length
    assert.equal(Number(h.match(/signature-row"><td colspan="(\d+)"/)[1]), cols, n + ' colspan = real column count')
  }
})
test('preserved: PTC/ICCT logos, school header, Letter page, table, filters/meta and data', async () => {
  for (const [n, h] of Object.entries(await pdfs())) for (const t of ['clms-logo.png', 'icct-logo.png', 'PATEROS TECHNOLOGICAL COLLEGE', 'Institute of Information and Computing Technology', '@page { size: 8.5in 11in', '<table class="pdf-table">', 'Generated:', 'break-after:avoid']) assert.ok(h.includes(t), `${n}: ${t}`)
  const r = (await pdfs()).Reports; assert.match(r, /Search filter: “ana”/); assert.match(r, /Total records: 1/)
})
test('Reports with more than 8 columns keeps its dense font and gets the signature row with the right colspan', async () => {
  global.localStorage = { getItem: () => JSON.stringify(me) }
  const cols = Array.from({ length: 10 }, (_, i) => 'c' + i), row = Object.fromEntries(cols.map(c => [c, 'v']))
  const h = (await U('reportsPdf.js')).buildReportsPdfHtml('Wide', cols, [row])
  assert.match(h, /font-size:6\.5pt/); assert.match(h, /signature-row"><td colspan="10"/)
})
test('no applicable module PDF source still contains "Printed by" output; the helper default for unflagged callers is unchanged', () => {
  for (const f of ['reportsPdf', 'auditLogPdf', 'maintenanceHistoryPdf', 'myReportsPdf', 'laboratoriesPdf', 'computersPdf', 'usersPdf', 'equipmentPdf']) {
    const s = fs.readFileSync(path.join(UT, f + '.js'), 'utf8'); assert.match(s, /signature: true/, f); assert.doesNotMatch(s.replace(/\/\/.*$/gm, ''), /Printed by/i, f)
  }
})
test('role permissions and print-button gating untouched: the four builders\' pages/routes are not part of this change', () => {
  const root = path.join(__dirname, '../..'); for (const f of ['client/src/pages/Reports.jsx', 'client/src/pages/MyReports.jsx', 'client/src/pages/AuditLog.jsx', 'client/src/pages/MaintenanceHistory.jsx']) { if (fs.existsSync(path.join(root, f))) assert.doesNotMatch(fs.readFileSync(path.join(root, f), 'utf8'), /signature/i, f) }
  assert.match(fs.readFileSync(path.join(root, 'server/routes/reportRoutes.js'), 'utf8'), /requireRole/)
})
